import{_ as i,c as l,aU as t,a as e}from"./chunks/framework.DIXiA2XH.js";const n=JSON.parse('{"title":"韩国好看的电影","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/韩国movie.md","filePath":"note/movie/韩国movie.md","lastUpdated":1773326622000}'),o={name:"note/movie/韩国movie.md"};function r(p,a,m,h,c,s){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="韩国好看的电影" tabindex="-1">韩国好看的电影 <a class="header-anchor" href="#韩国好看的电影" aria-label="Permalink to &quot;韩国好看的电影&quot;">​</a></h1><p>我原本吧，准备只开一篇记录下电影，但是呢，好电影实在是太多了，还是分类一下比较好，特别是韩国的电影，好看的实在是太多了，演技是真的牛逼。 你要说比特效，那肯定是美国电影，但你要说是比亲情，爱情、社会现实这种题材的，韩国必须第一。不信，你看完我下面推荐的再说信不信。</p><h2 id="七号房的礼物" tabindex="-1">七号房的礼物 <a class="header-anchor" href="#七号房的礼物" aria-label="Permalink to &quot;七号房的礼物&quot;">​</a></h2><ul><li>2013-01-23 韩国 127分钟</li><li>类型：剧情 家庭 喜剧</li><li>导演：李焕庆</li><li>主演：柳承龙 朴信惠 郑镇荣 金正泰 吴达洙</li><li>百科：1997年,只有6岁儿童智商的智障男子李龙久(柳成龙 饰)和可爱的女儿艺胜(葛素媛 饰)相依为命,生活虽然简单清贫,却充满幸福。某天,执着为女儿买美少女战士书包的龙久意外卷入一起幼童诱拐奸杀案,而死者竟是警察局长的女儿。龙久懵懂无知,搞不清状况,昏头昏脑就被投入监狱。在7号牢房中,聚集着走私犯蘇杨浩(吴达洙 饰)、诈骗犯崔春浩(朴元尚 饰)、通奸犯姜万范(金正泰 饰)、恐吓犯老徐(金基灿 饰)和抢劫犯申奉植(郑万植 饰)等五毒俱全的“社会渣滓”。龙久孩子般纯洁的心渐渐感动了这几个“大坏蛋”,他们甚至不惜冒险将艺胜带入牢房与父亲相会。 黑暗冰冷的监牢内,7号牢房阳光满满</li></ul><p>催人泪下的片子</p><p><img src="https://pic.rmb.bdstatic.com/bjh/3ad7bb159bad1e0534916a6f91a421ab.jpeg@h_1280" alt=""></p><h2 id="担保" tabindex="-1">担保 <a class="header-anchor" href="#担保" aria-label="Permalink to &quot;担保&quot;">​</a></h2><ul><li>2020-09-29 韩国 113分钟</li><li>类型：剧情 家庭 喜剧</li><li>导演：康大奎执导，尹济均编剧</li><li>主演：成东镒、河智苑、金熙元、朴昭怡</li><li>百科：该片讲述了两个高利贷业者在讨债时稀里糊涂的被对方将九岁的小女孩作为担保抵押给他们，不得不负责照顾小女孩的故事。</li></ul><p>催人泪下的片子</p><p><img src="https://m.ykimg.com/052600005F9F62692027EE08C8FFA768" alt=""></p><h2 id="开心家族" tabindex="-1">开心家族 <a class="header-anchor" href="#开心家族" aria-label="Permalink to &quot;开心家族&quot;">​</a></h2><ul><li>2010-12-23 韩国 111分钟</li><li>类型：剧情/喜剧</li><li>导演：金英卓</li><li>主演：车太贤、高昌锡、张英南、李文秀、千宝根</li><li>百科：该片讲述了因寂寞而寻求死亡的尚万遇到了一群大大咧咧的鬼，之后慢慢走向了人生巅峰的故事。</li></ul><p>催人泪下的片子</p><p><img src="https://m.ykimg.com/052600005D553A28425BD9AFDA15706A" alt=""></p><h2 id="傻瓜" tabindex="-1">傻瓜 <a class="header-anchor" href="#傻瓜" aria-label="Permalink to &quot;傻瓜&quot;">​</a></h2><ul><li>2008-02-28 韩国 106分钟</li><li>类型：喜剧、爱情</li><li>导演：金正权</li><li>主演：车太贤、河智苑、朴熙顺</li><li>百科：该片改编自韩国网络漫画家姜道英的同名漫画《傻瓜》，讲述在一条小村子里有位27岁还天真烂漫的傻瓜承龙，一边照顾着唯一的妹妹，一边等待外留学的初恋，终于在10年等待后，这位承龙心目中的天使回到了小村庄，重新相遇后二人发生的故事</li></ul><p>催人泪下的片子</p><p><img src="https://m.ykimg.com/052600005F69BBC914187C0798D79448" alt=""></p><h2 id="燃烧" tabindex="-1">燃烧 <a class="header-anchor" href="#燃烧" aria-label="Permalink to &quot;燃烧&quot;">​</a></h2><ul><li>2018-05-16 韩国 148分钟</li><li>类型：剧情 / 悬疑 / 犯罪</li><li>导演：李沧东</li><li>主演：刘亚仁 史蒂文·元 全钟瑞 金秀京 崔承浩 玉子妍</li><li>百科：目标成为作家的青年李钟秀（刘亚仁 饰），平日里靠兼职养活自己。经营畜牧业的父亲不谙人情，官司缠身，迫使钟秀又要为了搭救父亲而四处奔走。这一日，钟秀在某大型卖场重逢了当年的同学申惠美（全钟淑 饰）。惠美计划近期前往非洲旅行，于是拜托钟秀照看爱猫Boil。不久后惠美回国，与之一同下飞机的还有名叫本（史蒂文·元 饰）的男子。本驾驶保时捷，居住在高级公寓内，优哉游哉，不见工作，四处玩乐，和钟秀相比有如天上地下。不知为何，本走入平民钟秀和惠美的生活，更向新朋友讲述了他奇特的癖好。在钟秀家小聚的那个晚上过后，惠美仿佛人间蒸发了一般无影无踪……</li></ul><p>穷人和富人！非常值的看的片子！！！强烈推荐</p><p><img src="https://img0.baidu.com/it/u=2709338352,3005361438&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=800&amp;h=1141" alt=""></p><h2 id="寄生虫" tabindex="-1">寄生虫 <a class="header-anchor" href="#寄生虫" aria-label="Permalink to &quot;寄生虫&quot;">​</a></h2><ul><li>2019-05-21 韩国 132分钟</li><li>类型：剧情</li><li>导演：奉俊昊</li><li>主演：宋康昊 / 李善均 / 曹汝贞 / 崔宇植 / 朴素</li></ul><p>非常好的片子，强烈推荐</p><p><img src="https://picx.zhimg.com/v2-6567c4154a156cc9485c3dcb9a4c04a7.jpg?source=382ee89a" alt=""></p><h2 id="军舰岛" tabindex="-1">军舰岛 <a class="header-anchor" href="#军舰岛" aria-label="Permalink to &quot;军舰岛&quot;">​</a></h2><ul><li>2017年7月26日 韩国 132分钟</li><li>类型：剧情、历史、战争、动作</li><li>导演：柳承莞</li><li>主演：黄政民、苏志燮、宋仲基、李贞贤</li></ul><p>非常非常好看的片子，强烈建议！</p><p><img src="https://img1.baidu.com/it/u=1447210057,1097508338&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=1367&amp;h=800" alt=""></p>',30)])])}const u=i(o,[["render",r]]);export{n as __pageData,u as default};
